-- PT112-S1-Q1. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT112-S1-Q1$batch06$ AND q.stimulus=$batch06$Joanna: The only way for a company to be successful, after emerging from bankruptcy, is to produce the same goods or services that it did before going bankrupt. It is futile for such a company to try to learn a whole new business.
Ruth: Wrong. The Kelton Company was a major mining operation that went into bankruptcy. On emerging from bankruptcy, Kelton turned its mines into landfills and is presently a highly successful waste-management concern.$batch06$ AND q.prompt=$batch06$Ruth uses which one of the following argumentative techniques in countering Joanna's argument?$batch06$ AND q.correct_choice=$batch06$A$batch06$) THEN RAISE EXCEPTION 'Question changed: PT112-S1-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT112-S1-Q1$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S1-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT112-S1-Q1$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Ruth) Joanna is wrong.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Kelton went from mining to landfills after bankruptcy and is now highly successful.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Joanna's claim is absolute: the *only* way to succeed after bankruptcy is to stay in the same business. A single company that switched businesses and thrived breaks it. Kelton is that company. "Only" claims are made to be broken by one case.$batch06$), (3, $batch06$Goal$batch06$, $batch06$A counterexample to Joanna's claim.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT112-S1-Q1$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Kelton is the counterexample. It changed businesses after bankruptcy and succeeded, which is exactly what Joanna said cannot happen.$batch06$), ($batch06$B$batch06$, $batch06$No phenomenon gets a new explanation. Ruth just shows Joanna's rule fails.$batch06$), ($batch06$C$batch06$, $batch06$Kelton is not an analogy. It is a real case of exactly the kind Joanna was talking about.$batch06$), ($batch06$D$batch06$, $batch06$Nothing in Joanna's claim depends on a word with two meanings.$batch06$), ($batch06$E$batch06$, $batch06$Ruth is knocking down a claim, not building one by ruling out alternatives.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT112-S1-Q1$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
